# ======== vignette: freq-uncertainty-vis ========
# ---- setup ----
library(dplyr)
library(tidyr)
library(ggdist)
library(ggplot2)
library(broom)
library(distributional)

theme_set(theme_ggdist())

theme_set(theme_ggdist(base_size = 7))

# ---- data_gen ----
set.seed(5)
n = 10
n_condition = 5
ABC =
  tibble(
    condition = rep(c("A","B","C","D","E"), n),
    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)
  )

# ---- 89-data-plot (freq-uncertainty-vis: data_plot) ----
p <- withVisible({
ABC %>%
  ggplot(aes(x = response, y = condition)) +
  geom_point(alpha = 0.5) +
  ylab("condition")
})$value
save_plot(p, "89-data-plot")

# ---- m_ABC ----
m_ABC = lm(response ~ condition, data = ABC)

# ---- 90-halfeye (freq-uncertainty-vis: halfeye) ----
p <- withVisible({
m_ABC %>%
  tidy() %>%
  ggplot(aes(y = term)) +
  stat_halfeye(
    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = estimate, sigma = std.error))
  )
})$value
save_plot(p, "90-halfeye")

# ---- 91-halfeye-with-data (freq-uncertainty-vis: halfeye_with_data) ----
p <- withVisible({
ABC %>%
  expand(condition) %>%
  augment(m_ABC, newdata = ., se_fit = TRUE) %>%
  ggplot(aes(y = condition)) +
  stat_halfeye(
    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit)),
    scale = .5
  ) +
  # we'll add the data back in too (scale = .5 above adjusts the halfeye height so
  # that the data fit in as well)
  geom_point(aes(x = response), data = ABC, pch = "|", size = 2, position = position_nudge(y = -.15))
})$value
save_plot(p, "91-halfeye-with-data")

# ---- 92-gradientinterval (freq-uncertainty-vis: gradientinterval) ----
p <- withVisible({
ABC %>%
  expand(condition) %>%
  augment(m_ABC, newdata = ., se_fit = TRUE) %>%
  ggplot(aes(y = condition)) +
  stat_gradientinterval(
    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit)),
    scale = .5, fill_type = "gradient"
  )
})$value
save_plot(p, "92-gradientinterval")

# ---- 93-ccdfinterval (freq-uncertainty-vis: ccdfinterval) ----
p <- withVisible({
ABC %>%
  expand(condition) %>%
  augment(m_ABC, newdata = ., se_fit = TRUE) %>%
  ggplot(aes(y = condition)) +
  stat_ccdfinterval(
    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit))
  )
})$value
save_plot(p, "93-ccdfinterval")

# ---- 94-dotplot (freq-uncertainty-vis: dotplot) ----
p <- withVisible({
ABC %>%
  expand(condition) %>%
  augment(m_ABC, newdata = ., se_fit = TRUE) %>%
  ggplot(aes(y = condition)) +
  stat_dots(
    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit)),
    quantiles = 100
  )
})$value
save_plot(p, "94-dotplot")

# ---- m_mpg ----
m_mpg = lm(mpg ~ hp * cyl, data = mtcars)

# ---- 95-lineribbon (freq-uncertainty-vis: lineribbon) ----
p <- withVisible({
mtcars %>%
  group_by(cyl) %>%
  expand(hp = seq(min(hp), max(hp), length.out = 101)) %>%
  augment(m_mpg, newdata = ., se_fit = TRUE) %>%
  ggplot(aes(x = hp, fill = ordered(cyl), color = ordered(cyl))) +
  stat_lineribbon(
    aes(ydist = dist_student_t(df = df.residual(m_mpg), mu = .fitted, sigma = .se.fit)),
    alpha = 1/4
  ) +
  geom_point(aes(y = mpg), data = mtcars) +
  scale_fill_brewer(palette = "Set2") +
  scale_color_brewer(palette = "Dark2") +
  labs(
    color = "cyl",
    fill = "cyl",
    y = "mpg"
  )
})$value
save_plot(p, "95-lineribbon")

# ---- 96-lineribbon-lightened (freq-uncertainty-vis: lineribbon_lightened) ----
p <- withVisible({
mtcars %>%
  group_by(cyl) %>%
  expand(hp = seq(min(hp), max(hp), length.out = 101)) %>%
  augment(m_mpg, newdata = ., se_fit = TRUE) %>%
  ggplot(aes(x = hp, color = ordered(cyl))) +
  stat_lineribbon(aes(
    ydist = dist_student_t(df = df.residual(m_mpg), mu = .fitted, sigma = .se.fit),
    fill = ordered(cyl),
    fill_ramp = after_stat(level)
  )) +
  geom_point(aes(y = mpg), data = mtcars) +
  scale_fill_brewer(palette = "Set2") +
  scale_color_brewer(palette = "Dark2") +
  labs(
    color = "cyl",
    fill = "cyl",
    y = "mpg"
  )
})$value
save_plot(p, "96-lineribbon-lightened")
